using UnityEngine;
using UnityEngine.InputSystem;

namespace FarmPrototype.Farming
{
    public enum FarmTool { Hoe, Seeds, WateringCan, Harvest }

    public sealed class FarmTestPlot : MonoBehaviour
    {
        [SerializeField] private string playerName = "Player";
        [SerializeField] private int gridSize = 3;
        [SerializeField] private float tileSize = 2f;
        [SerializeField] private float plotDistanceFromPlayer = 7f;
        [SerializeField] private float interactionDistance = 7f;
        [SerializeField] private float growthDuration = 10f;

        private Transform player;
        private FarmTool activeTool;
        private int harvests;
        private string feedback = "Use 1 Enxada, 2 Sementes, 3 Regador ou 4 Colher.";

        private void Start()
        {
            var playerObject = GameObject.Find(playerName);
            player = playerObject != null ? playerObject.transform : null;
            CreatePlot();
        }

        private void Update()
        {
            var keyboard = Keyboard.current;
            if (keyboard != null)
            {
                if (keyboard.digit1Key.wasPressedThisFrame) activeTool = FarmTool.Hoe;
                if (keyboard.digit2Key.wasPressedThisFrame) activeTool = FarmTool.Seeds;
                if (keyboard.digit3Key.wasPressedThisFrame) activeTool = FarmTool.WateringCan;
                if (keyboard.digit4Key.wasPressedThisFrame) activeTool = FarmTool.Harvest;
            }

            if (Mouse.current != null && Mouse.current.leftButton.wasPressedThisFrame) TryInteract();
        }

        private void CreatePlot()
        {
            if (player == null)
            {
                feedback = "Player não encontrado.";
                return;
            }

            var forward = Camera.main != null ? Camera.main.transform.forward : player.forward;
            forward.y = 0f;
            if (forward.sqrMagnitude < 0.01f) forward = Vector3.forward;
            forward.Normalize();

            var center = player.position + (forward * plotDistanceFromPlayer);
            if (Physics.Raycast(center + (Vector3.up * 50f), Vector3.down, out var groundHit, 100f, ~0, QueryTriggerInteraction.Ignore))
                center.y = groundHit.point.y;

            var root = new GameObject("Farm_Test_Grid").transform;
            root.SetParent(transform, true);
            var offset = (gridSize - 1) * tileSize * 0.5f;
            for (var x = 0; x < gridSize; x++)
            {
                for (var z = 0; z < gridSize; z++)
                {
                    var tile = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    tile.name = $"Farm_Tile_{x}_{z}";
                    tile.transform.SetParent(root, true);
                    tile.transform.position = center + new Vector3((x * tileSize) - offset, 0.09f, (z * tileSize) - offset);
                    tile.transform.localScale = new Vector3(tileSize - 0.12f, 0.18f, tileSize - 0.12f);
                    tile.AddComponent<FarmTestTile>().Initialize(this, growthDuration);
                }
            }
            feedback = "Canteiro criado. Prepare, plante, regue e colha abóboras!";
        }

        private void TryInteract()
        {
            if (player == null || Camera.main == null) return;
            var ray = Camera.main.ScreenPointToRay(Mouse.current.position.ReadValue());
            foreach (var hit in Physics.RaycastAll(ray, 200f, ~0, QueryTriggerInteraction.Ignore))
            {
                var tile = hit.collider.GetComponent<FarmTestTile>();
                if (tile == null) continue;
                if (Vector3.Distance(player.position, tile.transform.position) > interactionDistance)
                {
                    feedback = "Chegue mais perto do canteiro.";
                    return;
                }
                feedback = tile.Use(activeTool);
                return;
            }
        }

        public void RegisterHarvest() => harvests++;

        private void OnGUI()
        {
            GUI.Box(new Rect(18f, 18f, 420f, 118f), "Fazenda — teste de cultivo");
            GUI.Label(new Rect(32f, 48f, 390f, 22f), $"Ferramenta: {ToolName(activeTool)}   |   Abóboras: {harvests}");
            GUI.Label(new Rect(32f, 72f, 390f, 22f), "1 Enxada  •  2 Sementes  •  3 Regador  •  4 Colher");
            GUI.Label(new Rect(32f, 96f, 390f, 32f), feedback);
        }

        private static string ToolName(FarmTool tool) => tool switch
        {
            FarmTool.Hoe => "Enxada", FarmTool.Seeds => "Sementes",
            FarmTool.WateringCan => "Regador", FarmTool.Harvest => "Colher", _ => "-"
        };
    }

    public sealed class FarmTestTile : MonoBehaviour
    {
        private enum State { Untilled, Tilled, Seeded, Watered, Growing, Ready }

        private static readonly Color UntilledColor = new(0.33f, 0.48f, 0.18f);
        private static readonly Color TilledColor = new(0.28f, 0.13f, 0.05f);
        private static readonly Color SeededColor = new(0.40f, 0.22f, 0.08f);
        private static readonly Color WateredColor = new(0.12f, 0.25f, 0.18f);
        private static readonly Color ReadyColor = new(0.22f, 0.42f, 0.10f);
        private static GameObject pumpkinSmall;
        private static GameObject pumpkinMedium;
        private static GameObject pumpkinLarge;

        private FarmTestPlot plot;
        private Renderer tileRenderer;
        private State state;
        private float middleAt;
        private float readyAt;
        private float growthDuration;
        private GameObject crop;

        public void Initialize(FarmTestPlot owner, float duration)
        {
            EnsureCropModelsLoaded();
            plot = owner;
            growthDuration = duration;
            tileRenderer = GetComponent<Renderer>();
            RefreshVisual();
        }

        private static void EnsureCropModelsLoaded()
        {
            if (pumpkinSmall == null) pumpkinSmall = Resources.Load<GameObject>("FarmCrops/Pumpkin_S");
            if (pumpkinMedium == null) pumpkinMedium = Resources.Load<GameObject>("FarmCrops/Pumpkin_M");
            if (pumpkinLarge == null) pumpkinLarge = Resources.Load<GameObject>("FarmCrops/Pumpkin_L");
            if (pumpkinSmall == null || pumpkinMedium == null || pumpkinLarge == null)
                Debug.LogError("Não foi possível carregar todos os modelos de abóbora em Resources/FarmCrops.");
        }

        private void Update()
        {
            if (state == State.Watered && Time.time >= middleAt)
            {
                state = State.Growing;
                RefreshVisual();
            }
            else if (state == State.Growing && Time.time >= readyAt)
            {
                state = State.Ready;
                RefreshVisual();
            }
        }

        public string Use(FarmTool tool)
        {
            if (tool == FarmTool.Hoe && state == State.Untilled)
            {
                state = State.Tilled; RefreshVisual(); return "Terra preparada. Plante uma semente (2).";
            }
            if (tool == FarmTool.Seeds && state == State.Tilled)
            {
                state = State.Seeded; RefreshVisual(); return "Abóbora plantada. Regue com a ferramenta 3.";
            }
            if (tool == FarmTool.WateringCan && state == State.Seeded)
            {
                state = State.Watered;
                middleAt = Time.time + (growthDuration * 0.5f);
                readyAt = Time.time + growthDuration;
                RefreshVisual();
                return $"Regada! A abóbora ficará pronta em {growthDuration:0} segundos.";
            }
            if (tool == FarmTool.Harvest && state == State.Ready)
            {
                state = State.Tilled; plot.RegisterHarvest(); RefreshVisual();
                return "Abóbora colhida. O canteiro pode receber outra semente.";
            }

            return tool switch
            {
                FarmTool.Hoe => "Esse canteiro já foi preparado.",
                FarmTool.Seeds => "Use sementes apenas em terra preparada.",
                FarmTool.WateringCan => "Plante uma semente antes de regar.",
                FarmTool.Harvest => "A abóbora ainda não está pronta.",
                _ => "Ação indisponível."
            };
        }

        private void RefreshVisual()
        {
            tileRenderer.material.color = state switch
            {
                State.Untilled => UntilledColor, State.Tilled => TilledColor, State.Seeded => SeededColor,
                State.Watered => WateredColor, State.Growing => WateredColor, State.Ready => ReadyColor, _ => UntilledColor
            };

            if (crop != null) Destroy(crop);
            crop = null;
            var model = state switch
            {
                State.Seeded or State.Watered => pumpkinSmall,
                State.Growing => pumpkinMedium,
                State.Ready => pumpkinLarge,
                _ => null
            };

            if (model == null) return;
            crop = Instantiate(model);
            crop.name = $"Pumpkin_{state}";
            crop.transform.position = transform.position + (Vector3.up * 0.18f);
            crop.transform.rotation = Quaternion.identity;
            crop.transform.localScale = Vector3.one * 0.75f;
            crop.transform.SetParent(transform, true);
            foreach (var cropCollider in crop.GetComponentsInChildren<Collider>()) Destroy(cropCollider);
        }
    }
}
